// SAF rank insignia, traced from MINDEF's own artwork.
//
// Not a lucide icon and not drawn like one: these are FILLED silhouettes on a portrait
// grid, where every lucide glyph is a 24-square stroked outline. A chevron stack rendered
// as strokes turns to mud below about 20px, and rank is read at a glance in a list — so
// the shape is the ink. `fill` is nonzero (the browser default), which is what lets the
// laurels and the state crest overlap themselves without punching holes.
//
// The grid is 22 wide by 31 tall. Sizing is by HEIGHT, since that is the dimension a
// rank actually grows along as it gains chevrons; width follows at 22/31.
//
// Provenance, and how to regenerate: docs/rank-icons.md. The paths are build output —
// edit the generator, never these strings.

const VIEW_BOX = '0 0 22 31'
const ASPECT = 22 / 31

// Rank abbreviations in order of seniority, grouped as the SAF groups them.
export const RANK_GROUPS = [
  // REC is a real rank and carries NO insignia — a recruit wears a bare patch. It is listed
  // here because it is a rank, and deliberately absent from RANK_PATHS because there is
  // nothing to draw. rankKey() returns null for it; rankLabel() still tidies it up.
  { name: 'Enlisted', ranks: ['REC', 'PFC', 'LCP', 'CPL', 'CFC'] },
  { name: 'Specialist', ranks: ['3SG', '2SG', '1SG', 'SSG', 'MSG'] },
  { name: 'Warrant Officer', ranks: ['3WO', '2WO', '1WO', 'MWO', 'SWO', 'CWO'] },
  { name: 'Officer', ranks: ['2LT', 'LTA', 'CPT', 'MAJ', 'LTC', 'SLTC', 'COL', 'BG', 'MG', 'LG'] },
  // A Military Expert is held at a SUB-rank — ME3-2, never plain ME3 — and ME1 to ME7 all
  // start at their -1. Only ME8 and ME9 are held bare. The device does not change with the
  // sub-rank: every ME3-n wears the ME3 insignia, so RANK_PATHS is keyed by the parent and
  // the sub-rank lives only in the label. ME4A is a rank in its own right, not a sub-rank.
  { name: 'Military Expert', ranks: ['ME1-1', 'ME1-2', 'ME2-1', 'ME2-2', 'ME3-1', 'ME3-2', 'ME3-3', 'ME4-1', 'ME4-2', 'ME4-3', 'ME4A', 'ME5-1', 'ME5-2', 'ME6-1', 'ME6-2', 'ME6-3', 'ME7-1', 'ME7-2', 'ME7-3', 'ME8', 'ME9'] },
]
export const RANKS = RANK_GROUPS.flatMap((g) => g.ranks)

