// A rank as stored is free text an admin typed, so match it loosely: case and any
// punctuation or spacing are ignored ("3sg", "3 SG", "ME-4" all land). Anything that
// still misses returns null and the caller falls back to showing the text it was given —
// better a legible "CPT(NS)" than a blank square.
// Canonical spelling of whatever an admin typed: upper case, punctuation and spacing gone,
// and a Military Expert sub-rank put back together with its hyphen — "me3 2", "ME3/2" and
// "ME3-2" all land on ME3-2. ME4A survives untouched because 'A' is not a sub-rank number.
function canonRank(rank) {
  const k = String(rank || '').toUpperCase().replace(/[^A-Z0-9]/g, '')
  const sub = /^ME(\d)(\d)$/.exec(k)
  return sub ? `ME${sub[1]}-${sub[2]}` : k
}

// The key of the INSIGNIA to draw, which is not always the rank: every ME3-n wears the ME3
// device. Returns null when there is nothing to draw (REC, or anything unrecognised).
export function rankKey(rank) {
  const c = canonRank(rank)
  if (RANK_PATHS[c]) return c
  const sub = /^(ME\d)-\d$/.exec(c)
  return sub && RANK_PATHS[sub[1]] ? sub[1] : null
}

export function hasRankInsignia(rank) { return rankKey(rank) !== null }

// The tidied spelling of a rank, insignia or not — so a typed "rec" shows as "REC". Falls
// back to whatever was typed when it matches no rank at all, because a value the app does
// not recognise is still the admin's own text and hiding it would lose information.
const ALL_RANKS = new Set(RANKS)
export function rankLabel(rank) {
  const c = canonRank(rank)
  return ALL_RANKS.has(c) ? c : String(rank || '').trim()
}

// Where the ink actually sits inside the 22x31 box, as [x, y, width, height] in box units —
// measured with getBBox on the rendered paths, not estimated.
//
// This is the whole reason the component crops. Every rank shares the box, but almost none
// of them fills it: PFC's single chevron lives at y 1.5-7.1, a 2LT bar floats at 14.3-16.7,
// and only LG reaches the bottom. Drawn as-is they all occupy the same tall rectangle, so a
// short rank hangs in mid-air with a pile of empty box beneath it — which reads as the
