// The Military Expert ranks are the one family scaled to FILL the box; everyone else holds
// true scale. The reason is what the icon claims when it is enlarged.
//
// Across the other families, enlarging each rank to fit makes LTA's two bars heavier than
// CPT's three and MAJ's crest fatter than COL's — the picture then says the opposite of the
// seniority. Holding one scale keeps every chevron and bar the same width across all of
// them, so the COUNT is the only thing that varies, which is how a rank is actually read.
//
// The MEs are read differently: the device is one diamond over a bar stack, and at true
// scale ME1 through ME4 shrink to a smudge. They also never sit beside the other families —
// a man is an ME or he is not — so the comparison that would be broken is not one anyone
// makes. Filling costs a little (ME1's diamond comes out larger than ME7's) and buys the
// bar count back, which is the whole of what distinguishes them.
const FILLED_RANKS = new Set(Object.keys(RANK_PATHS).filter((k) => k.startsWith('ME')))
// The tallest ink in the set (28 of 31 units). A filled rank is capped here rather than at
// the full box, so an ME can never draw taller than an LG does at true scale.
const TALLEST_INK = 28 / 31

// `size` is what the FULL 31-unit box would measure in px, not what this rank will.
// `maxWidth` is the width the caller has to spare, and only the filled ranks consult it.
// Give it a fixed-height container and centre the SVG in it. The returned height varies per
// rank, so anything else lets the short ranks drift: bottom-aligning strands a 2px 2LT bar on
// the label, top-aligning strands it against the card's top edge.
export function RankInsignia({ rank, size = 24, maxWidth = Infinity, ...rest }) {
  const key = rankKey(rank)
  if (!key) return null
  const [x, y, w, h] = RANK_INK[key]
  const filled = FILLED_RANKS.has(key)
  const scale = filled ? Math.min(maxWidth / w, (size * TALLEST_INK) / h) : size / 31
  // True scale keeps the full 22-wide box so every chevron lands on the same centre line at
  // the same width; filled ranks crop to their own ink, which is what lets them grow.
  const vw = filled ? w : 22
  return (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox={filled ? `${x} ${y} ${w} ${h}` : `0 ${y} 22 ${h}`}
      width={vw * scale} height={h * scale} fill="currentColor"
      role="img" aria-label={key} {...rest}>
      <path d={RANK_PATHS[key]} />
    </svg>
  )
}
